fn rendered<D:Demand>(demand:&D,args:std::fmt::Arguments<'_>)->Result<String,D::Error>{use std::fmt::Write;struct Count(usize);impl Write for Count{fn write_str(&mut self,text:&str)->std::fmt::Result{self.0=self.0.checked_add(text.len()).ok_or(std::fmt::Error)?;Ok(())}}struct Fixed<'a>(&'a mut String);impl Write for Fixed<'_>{fn write_str(&mut self,text:&str)->std::fmt::Result{if text.len()>self.0.capacity()-self.0.len(){return Err(std::fmt::Error)}self.0.push_str(text);Ok(())}}let mut count=Count(0);count.write_fmt(args).map_err(|_|demand.resource("procedure diagnostic size overflow"))?;let bound=count.0.checked_mul(4).ok_or_else(||demand.resource("procedure diagnostic capacity overflow"))?;demand.storage(bound.checked_add(std::mem::size_of::<String>()+128).ok_or_else(||demand.resource("procedure diagnostic admission overflow"))?)?;let mut message=String::new();message.try_reserve_exact(count.0).map_err(|_|demand.resource("procedure diagnostic allocation refused"))?;if message.capacity()>bound{return Err(demand.resource("procedure diagnostic exposed excess capacity"))}Fixed(&mut message).write_fmt(args).map_err(|_|demand.resource("procedure diagnostic exceeded counted width"))?;Ok(message)}
fn fund_note<D:Demand>(source:dm_tree::frontend::BorrowedSourceNoteOrigin<'_>,message:&str,demand:&D)->Result<(),D::Error>{let(path,_,_)=source.reported_coordinates();demand.storage(path.as_os_str().len().checked_mul(8).and_then(|n|n.checked_add(message.len().checked_mul(4)?)).and_then(|n|n.checked_add(4*std::mem::size_of::<Note>()+1024)).ok_or_else(||demand.resource("procedure note admission overflow"))?)}

